from lib import *
P('ka-te','Ka Te'); P('bu-prang','Bu Prăng'); P('duc-lap','Đức Lập'); P('song-luy','Sông Lũy'); P('u-minh','U Minh Thượng')
D='vietnam-hanoi'; OP=['vietnam-operations']
E('uminh-0926','1969-09-26','Sept. 26','U Minh Thượng, Region 9. Saigon opens a sweep with 23 battalions, the long sweeps of Bà Hòn, Chương Thiện and U Minh Thượng aimed at the border, the supply corridor and the Region\'s preparations for spring 1970. Fifty guerrilla teams, 200 men, ambush river craft on the Ông Đốc; hundreds out of action, dozens of boats sunk or badly hurt.','147–48',also=OP,place='u-minh',check='the end of the sweep; the history gives the period only.',lw='U Minh Thượng sweep of 23 battalions')
E('kate','1969-11-02','Nov. 2','Ka Te, Hill 936, Quảng Đức. At 4 a.m. the 66th Regiment storms the base from its trenches, after five days of closing in; in 15 minutes the garrison is destroyed. Nearly 200 out of action, 14 aircraft shot down, six 105 mm and 155 mm guns taken.','150–51',also=OP,place='ka-te',t='04:00',us=True,see='cal.1969-10-29.vietnam-hanoi',words='"Bốn giờ sáng ngày 2-11-1969" (4 a.m., Nov. 2, 1969).',lw='Ka Te stormed by the 66th Regiment')
E('duclap-1102','1969-11-02','Nov. 2–6','Đức Lập and Đắk Song. On the campaign\'s main axis the Front\'s forces surround Đức Lập to draw the Saigon forces out toward Đắk Song and destroy them.','151',also=OP,place='duc-lap',see='cal.1969-10-29.vietnam-hanoi',lw='Đức Lập surrounded to draw out Saigon forces')
E('buprang-1109','1969-11-09','Nov. 9','Bu Prăng to Đức Lập. With artillery in support the infantry takes a series of posts along the line. The 66th Regiment presses west of Bu Prăng and Hills 882 and 883; Saigon sends Task Force 220 and two reconnaissance companies to relieve.','151',also=OP,place='bu-prang',see='cal.1969-10-29.vietnam-hanoi',lw='Bu Prăng: the posts along the line attacked')
E('tf220','1969-11-17','Nov. 17','Bu Prăng. Saigon\'s Task Force 220, sent to relieve the base, is badly hurt by the 66th Regiment.','151',also=OP,place='bu-prang',see='buprang-1109',lw='Task Force 220 hurt at Bu Prăng')
E('tf22','1969-11-21','Nov. 21','Bu Prăng. Saigon puts Task Force 22 in place of 220; the 66th Regiment, Battalion 37 and Sapper Company 60 meet it and hurt it, and it falls back south of the base.','151',also=OP,place='bu-prang',see='tf220',lw='Task Force 22 hurt at Bu Prăng')
E('buprang-1130','1969-11-30','Nov. 30','Bu Prăng. Sappers take the Task Force 22 headquarters and the base, held completely by the Front\'s forces.','151–52',also=OP,place='bu-prang',see='tf22',lw='Bu Prăng base taken')
C('cal.1969-10-29.vietnam-hanoi','152 and n. 1','the campaign ends Dec. 5: Task Forces 220 and 53 and a mixed infantry and ranger task force put out of action, 103 aircraft (mostly helicopters), 87 vehicles (24 armored), 29 guns and mortars and 35 depots destroyed or damaged, by the history\'s count','E')
E('winter-r6','1969-12','Dec., winter','Region 6 and Tuyên Đức. Region 6\'s sappers raid the rear base of the Saigon 44th Regiment, 23d Division, at Sông Lũy, Bình Thuận. At Đức Trọng and on Route 21 the main force and local forces hurt many Civil Guard companies, take some posts and help the people break strategic hamlets along Routes 20 and 21.','149',also=OP,place='song-luy',at='before 1969-12-21',check='the days; the history gives the winter phase.',lw='Region 6 and Tuyên Đức, winter phase')
E('saigon-0125','1969-01-25','Jan. 25','Saigon. More than 10,000 people of different classes, parties and religions march to demand that the United States end the war and withdraw its and its allies\' troops, that Thiệu, Kỳ and Hương resign, and that a peace government be formed. Seminars and petitions follow in Saigon, Đà Nẵng, Huế, Cần Thơ and other towns.','155–56',th='vietnam-saigon',also=[D],place='saigon',polity='rvn',check='the day and the number; the history gives them in its own account, with no Saigon or American source.',lw='Saigon march of 10,000 for peace')
E('saigon-0505','1969-05','May','Saigon. 11,000 airport and railway workers strike, hindering supply of American and Saigon units.','156',th='vietnam-saigon',also=[D],place='saigon',polity='rvn',check='the days; the history gives the month.',lw='Saigon airport and rail workers strike')
E('saigon-0708','1969-07','July','Saigon. Thiệu\'s government makes students take military training in the summer vacation; over 30,000 demonstrate and petition. The police shoot the student Thái Văn Hiền, and a military vehicle runs down Nguyễn Mạnh Hùng. Students strike and meet in Đà Lạt, Huế and Cần Thơ against military training in the schools.','157–58',th='vietnam-saigon',also=[D],place='saigon',polity='rvn',check='the days; the history gives the month for the order and none for the deaths.',ok=['ok:fields-at'], lw='Saigon students against military training')
E('saigon-0808','1969-08','Aug.','Saigon. The bus company\'s workers strike; 1,000 delegates elected at the congresses of 118 unions back them, and workers of Esso, Caltex, the cosmetics firm, the Mic tobacco works and Grall Hospital strike in support. By early 1970 over 30,000 workers of 64 plants are out; 40 military ships and hundreds of flights are held up. In Feb. 1970 the Thủ Đức depot\'s workers strike, drawing 7,000 more.','156–57',th='vietnam-saigon',also=[D],place='saigon',polity='rvn',check='the days; the history gives Aug. 1969 for the start and 1970 for the rest.',lw='Saigon bus workers and others strike')
E('qgtb','1969','1969, mid','The Saigon–Gia Định Party Committee moves the lawyer Trần Ngọc Liễng, a sympathizer, to found the Progressive National Force, of Saigon officials weary of war and not hostile to the revolution, to press Thiệu to end the war.','158',th='vietnam-saigon',also=[D],at='before 1969-05',vis=True,check='the day; the history says "giữa năm 1969".',ok=['ok:fields-place'], lw='Progressive National Force founded in Saigon')
E('plenum18','1970-01','Jan.','The Party Central Committee\'s 18th plenum meets in Hanoi on the direction of the leadership of the revolution in the South in the new stage. It affirms the gains of 1968 and 1969, criticizes shortcomings, judges that Vietnamization will continue and the war may spread north, to Laos and Cambodia, and in the main agrees with the Politburo\'s April 1969 estimate of two courses. The tasks: press the military and political attack with diplomacy; the countryside the main direction; build the rear, including the fuel pipeline; the North ready to fight and support the South, Laos and Cambodia.','158–62',also=['vietnam-operations'],place='hanoi',vis=True,check='the days; the history gives "tháng 1-1970". The calendar\'s span ends Jan. 19, 1970.',lw='The 18th plenum of the Central Committee')
